<main class="mdq-page"><div class="mdq-wrap mdq-detail"><div class="mdq-breadcrumb"><a href="<?= $home; ?>">Home</a> &nbsp;/&nbsp; <a href="<?= $home; ?>/products">Shop medicines</a> &nbsp;/&nbsp; <?= htmlspecialchars($product->item_name); ?></div><div class="mdq-detail-grid"><div class="mdq-detail-media"><?php if($img): ?><img src="<?= htmlspecialchars($img,ENT_QUOTES); ?>" alt="<?= htmlspecialchars($product->item_name); ?>"><?php else: ?><span class="mdq-detail-placeholder" aria-hidden="true"><?= htmlspecialchars((string)($store->store_name ?? 'Pharmacy')); ?></span><?php endif; ?></div><div><div class="mdq-detail-category"><?= htmlspecialchars($product->category_name??'Pharmacy essential'); ?></div><h1><?= htmlspecialchars($product->item_name); ?></h1><div class="mdq-detail-price"><?= sf_currency($price,$cur); ?></div><div class="mdq-detail-stock"><?= $isOut?'Currently unavailable':'Available for delivery or pickup'; ?></div><div class="mdq-detail-desc"><?= nl2br(htmlspecialchars($product->description??'')); ?></div><?php $this->load->view('themes/shared/variant_picker'); ?><div class="mdq-qty"><button type="button" onclick="adjustDetailQty(-1)" aria-label="Decrease quantity"><svg class="mdq-inline-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12h14"></path></svg></button><span id="detail-qty">1</span><button type="button" onclick="adjustDetailQty(1)" aria-label="Increase quantity"><svg class="mdq-inline-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M12 5v14M5 12h14"></path></svg></button></div><div class="mdq-detail-actions"><button class="mdq-btn mdq-btn-primary" type="button" onclick="addDetailToCart()" <?= $isOut?'disabled':''; ?>><?php if(!$isOut): ?><svg class="mdq-inline-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M3 4h2l2.3 11.2a2 2 0 0 0 2 1.6h7.9a2 2 0 0 0 1.9-1.5L21 8H6"></path><circle cx="10" cy="20" r="1"></circle><circle cx="18" cy="20" r="1"></circle></svg><?php endif; ?><?= $isOut?'Out of stock':'Add to cart'; ?></button><a class="mdq-btn mdq-btn-soft" href="<?= $home; ?>/cart"><svg class="mdq-inline-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M3 4h2l2.3 11.2a2 2 0 0 0 2 1.6h7.9a2 2 0 0 0 1.9-1.5L21 8H6"></path><circle cx="10" cy="20" r="1"></circle><circle cx="18" cy="20" r="1"></circle></svg>View cart</a></div><div class="mdq-note"><strong>Need help with this medicine?</strong>Ask a pharmacist about suitability, dosage and how to use it. A prescription may be required for some products.</div><?php if($isOut&&!empty($settings->whatsapp_number)): ?><a class="mdq-btn mdq-btn-soft" style="margin-top:13px" href="https://wa.me/<?= preg_replace('/[^0-9]/','',$settings->whatsapp_number); ?>?text=<?= urlencode('Hello, is '.$product->item_name.' available?'); ?>" target="_blank" rel="noopener">Ask about availability</a><?php endif; ?></div></div></div></main>
<script>let detailQty=1;const detailProduct={id:<?= (int)$product->id; ?>,type:<?= json_encode($type); ?>,name:<?= $jsName; ?>,price:<?= json_encode((float)$price); ?>,image:<?= $jsImage; ?>,stock:<?= (int)($product->stock??0); ?>};function adjustDetailQty(d){detailQty=Math.max(1,detailQty+d);document.getElementById('detail-qty').textContent=detailQty}function addDetailToCart(){const p=window.sfPickedVariant||detailProduct;if(typeof addToCart==='function')addToCart(p.id,detailProduct.type==='physical'?'product':detailProduct.type,p.name,p.price,p.image,detailQty,p.stock)}</script>
